gs_provision.config:
    1
    {{xml .Line.AccountLabel}}
    {{xml .Server.Host}}:{{.Server.Port}}
    {{xml .Line.Username}}
    {{xml .Line.AuthName}}
    {{xml .Line.Password}}
    {{xml .Line.DisplayName}}
    0
{{- /* HD voice: Preferred Vocoder choices 1 to 6 of account 1 (P57, P58, P59, P60, P61, P62; Grandstream config templates, "Preferred Vocoder"): 0 PCMU, 8 PCMA, 9 G.722, 123 Opus (the models that have it; payload type P2385 stays at its default 123). Order Opus (the models that have it), G.722, PCMU, PCMA; the choices after the last codec repeat it, which the phone ignores, so no other codec is offered. Another account of a multi-account model has its own choice keys (account 2 P451 to P456, account 3 P551 to P556, and so on in steps of 100); Hello provisions account 1. Unverified on hardware (verify). */}}
{{- if .Codecs.Opus}}
    123
    9
    0
    8
    8
    8
{{- else}}
    9
    0
    8
    8
    8
    8
{{- end}}
    {{div .Server.Expiry 60}}
{{- /* MWI (spec S-1): P99 = Subscribe for MWI [R8x6 TPL, R8x6 section 5; WP822 same key]; P33 = voicemail access number, defaulting to Hello's voicemail feature code. */}}
    1
    {{xml (or .Line.VoicemailCode "*97")}}
{{- /* Text messages (SIP MESSAGE, RFC 3428): P22650 = 1 makes account 1 the designated account for instant messaging (WP8x6 Administration Guide "Instant Message" and the phone-feature-parity spec S-8, R8x6 section 5). Hello answers 202/200 and delivers to every phone of the extension. UNVERIFIED on hardware: not confirmed on a WP826 or WP822, and the value (1 = account 1) is read from the guide, not from a phone's exported configuration. Phones without the key ignore it. */}}
    1
{{- /* Call waiting (phone-feature-parity S-18), written from the extension's flag so the phone agrees with Hello. P26063 = account 1 "Enable Call Waiting" (WP8x6) / "Disable Call Waiting" (WP822): 1 = on, 2 = off in both templates (wp8x6_config_1.0.3.39 reads 0 Default, 1 Yes, 2 No; wp810_822_825_config_1.0.11.83 reads 0 Default, 1 No, 2 Yes, the question inverted). P91 = the phone-wide switch: 0 = on, 1 = off in both. P186 = "Enable Call Waiting Tone" (WP8x6 and WP820 templates): 0 = tone, 1 = no tone; the WP822 template has no such key and ignores it, its tone is P347/P1555 which stay at the phone default. Taken from Grandstream's published config templates, not yet confirmed on a phone (verify, lab item 26). */}}
{{- /* The WP856 template (wp856_config_1.0.3.16: "Enable Call Waiting. 0 Default, 1 No, 2 Yes") reads P26063 the other way round: 2 = on, 1 = off, and has no P91 or P186. */}}
{{- if .Phone.CWInverted}}
    {{if .Line.CallWaiting}}2{{else}}1{{end}}
{{- else if .Line.CallWaiting}}
    1
    0
    0
{{- else}}
    2
    1
    1
{{- end}}
{{- /* Feature Key Synchronization (spec S-7): the phone's DND and call-forward keys follow Hello and Hello's follow the phone, over SUBSCRIBE/NOTIFY Event: as-feature-event. P2325 = Feature Key Synchronization, account 1 (account 2 is P2425, 3 is P2525); P198 = Special Feature, 102 = Broadsoft, which the Administration Guide says the feature needs ("When using this feature, Special Feature needs to be set to BroadSoft"). Both keys are in Grandstream's own config templates (config-template-10212026.zip) for the GXP11xx/14xx/16xx/21xx/22xx, GRP26xx, WP810/820/822/825/856/8x6 and DP75x with the same numbers on every model; the WP820 template documents P2325 as "0 Disable, 1 BroadSoft/Metaswitch". Verified against the vendor templates and guides, not on a phone (verify). */}}
    102
    1
{{- /* Local call features (spec S-7): P191 = Enable (Local) Call Features, default 1 on the WP8x6 and WP810/822/825 and 0 on the WP856. On, the phone acts on *72/*73/*90-*93 and its own DND and forward menus itself and Hello never sees them. Off, the phone dials the codes to Hello, whose feature codes are written below as the strings the DND and forward keys dial. Switching it off also hands the phone's other star codes (caller ID *67/*82, call waiting *70/*71) to Hello, which does not implement them. Keys per Grandstream's templates: WP8x6 (wp8x6_config_1.0.3.39) P2344/P2345 DND on/off, P26013/P26014 forward always on/off, P26009/P26010 busy, P26011/P26012 no answer (the _target fields P29092-P29094 stay empty so the user's key asks for the number); WP856 (wp856_config_1.0.3.16) only P2344/P2345; WP810/822/825 (wp810_822_825_config_1.0.11.83) only P191. Record key: the WP8x6 P26028/P26029 are the codes the Record key sends to turn recording on and off (P29066 = 0 key default: on), set to Hello's *1 toggle; the WP856 P6760 = 2 Record Mode "on UCM" hands recording to the server. Verified in the vendor templates, not on a phone (verify). */}}
    0
{{- with .Codes.DNDOn}}
{{- if or (eq $.Phone.Family "8x6") (eq $.Phone.Family "856")}}
    {{xml .}}
{{- end}}
{{- end}}
{{- with .Codes.DNDOff}}
{{- if or (eq $.Phone.Family "8x6") (eq $.Phone.Family "856")}}
    {{xml .}}
{{- end}}
{{- end}}
{{- if eq .Phone.Family "8x6"}}
{{- with .Codes.ForwardOn}}
    {{xml .}}
{{- end}}
{{- with .Codes.ForwardOff}}
    {{xml .}}
{{- end}}
{{- with .Codes.ForwardBusyOn}}
    {{xml .}}
{{- end}}
{{- with .Codes.ForwardBusyOff}}
    {{xml .}}
{{- end}}
{{- with .Codes.ForwardNoAnswerOn}}
    {{xml .}}
{{- end}}
{{- with .Codes.ForwardNoAnswerOff}}
    {{xml .}}
{{- end}}
    0
    *1
    *1
{{- end}}
{{- if eq .Phone.Family "856"}}
    2
{{- end}}
{{- /* Emergency numbers from Hello's emergency routes (CALL-47): P8385 on the WP8x6, P25675 on the WP856; the WP8xx template has none. Call park and retrieve codes (CALL-16): P60069 and P2336 on the WP8x6 and WP856. */}}
{{- if .Emergency}}
{{- if eq .Phone.Family "8x6"}}
    {{xml .Emergency}}
{{- else if eq .Phone.Family "856"}}
    {{xml .Emergency}}
{{- end}}
{{- end}}
{{- if or (eq .Phone.Family "8x6") (eq .Phone.Family "856")}}
{{- if .Line.ParkCode}}
    {{xml .Line.ParkCode}}
{{- end}}
{{- if .Line.ParkRetrieveCode}}
    {{xml .Line.ParkRetrieveCode}}
{{- end}}
{{- end}}
{{- /* BLF keys (CALL-43): the P323 block is defined by none of the WP templates (WP8x6, WP856, WP8xx), so it is written only to a Grandstream phone that is not a WP (Phone.Family empty). prov.SupportsBLF refuses BLF keys on a WP in the API. */}}
{{- if not .Phone.Family}}
{{- range $i, $k := .BLF}}

1

0

{{xml $k.Number}}
{{- end}}
{{- end}}

{{- if eq .Phone.Family "856"}}
    2
{{- else}}
    1
{{- end}}
{{- /* Paging button, multicast paging, PTT and group paging (phone-feature-parity S-30, phonebooks-ptt P-15). Keys from Grandstream's own config templates (Grandstream config-template-10212026.zip): wp8x6_config_1.0.3.39 (WP816/826/836), wp856_config_1.0.3.16, wp810_822_825_config_1.0.11.83 (WP810/822/825), wp820_config_1.0.7.90, and the WP8x6 Administration Guide "PTT/Paging". Every Grandstream: P22208 multicast paging on, P1568 codec (0 PCMU, 8 PCMA, 9 G.722), P1569 and up listening address and label pairs (ten slots), P1566 paging barge (0 off, 1-10), P1567 paging priority active, P26019 barge by Call-Info/Alert-Info (intercom barging, default off). WP8x6 and WP8xx: P8381 page in DND. WP8x6: P22532 multicast call timeout (s), P22556 PTT/Paging switch. WP8x6 and WP856: P82317 side key (0 PTT/Paging), P26072 beep before an auto answer, P26071 do not mute on answer. PTT (WP8x6, WP856, WP8xx, WP820): P22177 PTT, P22183 PTT/group paging address, P22184 default, P22185 priority, P22186 emergency channel, P22179 accept while busy, P22180 codec; group paging: P22194 on, P22199 default, P22200 priority, P22201 emergency group, P22196 accept while busy, P22197 codec. Channel slots: WP8x6, WP856 and WP8xx at P82001 + 5 (n-1) for channels 1 to 50 (available, transmit, subscribe, join, name); the WP820 as digit strings P22187-P22192 (PTT) and P22203-P22207 (group), with its own codec numbers (0 G.711, 1 G.722). The WP8xx template has no PTT keys although its handset has PTT (WP8xx User Guide, "PTT (Push-to-talk) functionality"): the WP8x6 keys are written to it unverified. A WP always gets PTT (its PTT key otherwise reads "not configured"): channel 1 on the catalog's PTT channel unless its group says otherwise. All unverified on a phone (verify). */}}
{{- $wp := .Phone.WP}}
{{- if or (eq $wp "WP8x6") (eq $wp "WP856") (eq $wp "WP820")}}
    1
    0
{{- end}}
{{- with .Paging}}
    {{.IntercomBarge}}
{{- end}}
{{- with .Multicast}}
    1
    {{.GSCodec}}
{{- range .ListenSlots}}

{{xml .HostPort}}

{{xml .Label}}
{{- end}}
{{- with $.Paging}}
    {{.Barge}}
    {{.PriorityActive}}
{{- if or (eq $wp "WP8x6") (eq $wp "WP8xx")}}
    {{.AllowInDND}}
{{- end}}
{{- if eq $wp "WP8x6"}}
    {{.Timeout}}
{{- end}}
{{- end}}
{{- end}}
{{- if or (and .PTT (or .PTT.Enabled .PTT.GroupPaging)) (and .Multicast .Multicast.PagingKey)}}
{{- if eq $wp "WP8x6"}}
    1
{{- end}}
{{- if or (eq $wp "WP8x6") (eq $wp "WP856")}}
    0
{{- end}}
{{- end}}
{{- with .PTT}}
{{- if or .Enabled .GroupPaging}}
    {{xml .Address}}
{{- end}}
{{- if .Enabled}}
    1
    {{.DefaultChannel}}
    {{.PriorityChannel}}
    {{.EmergencyChannel}}
    {{.AcceptBusy}}
{{- if eq $wp "WP820"}}
    {{.CodecWP820}}
    {{.ChannelMasks.Available}}
    {{.ChannelMasks.Available}}
    {{.ChannelMasks.Transmit}}
    {{.ChannelMasks.Subscribe}}
    {{xml .ChannelMasks.Labels}}
{{- else}}
    {{.CodecGS}}
{{- range .Channels}}

{{.Available}}

{{.Transmit}}

{{.Subscribe}}

{{.Available}}

{{xml .Label}}
{{- end}}
{{- end}}
{{- else}}
    0
{{- end}}
{{- if .GroupPaging}}
    1
    {{.DefaultGroup}}
    {{.PriorityGroup}}
    {{.EmergencyGroup}}
    {{.AcceptBusy}}
{{- if eq $wp "WP820"}}
    {{.CodecWP820}}
    {{.GroupMasks.Available}}
    {{.GroupMasks.Available}}
    {{.GroupMasks.Transmit}}
    {{.GroupMasks.Subscribe}}
    {{xml .GroupMasks.Labels}}
{{- else}}
    {{.CodecGS}}
{{- range .Groups}}

{{.Available}}

{{.Transmit}}

{{.Subscribe}}

{{.Available}}

{{xml .Label}}
{{- end}}
{{- end}}
{{- else}}
    0
{{- end}}
{{- end}}
    {{xml .Phone.AdminPassword}}
    {{urlvia .Prov.URL}}
{{- /* P8433 (PRV-04) is defined only in the WP8x6 template; the WP856 and WP8xx templates load CAs through the web UI. */}}
{{- if and .Prov.CACertPEM (ne .Phone.Family "856") (ne .Phone.Family "8xx")}}
    {{xml .Prov.CACertPEM}}
{{- end}}
    {{xml (noscheme .Prov.URL)}}
    0
{{- /* Automatic upgrade (PRV-06): P194 on the WP8x6 and WP8xx, P22296 on the WP856. A pin's upgrade window (spec S-26) makes P194 = 2, daily at the hour in P285 (config changes then reach the phone by check-sync or at that hour); the WP856 key for it is unverified, so the window is not rendered there. */}}
{{- if eq .Phone.Family "856"}}
    1
{{- else if and .Firmware .Firmware.Window}}
    2
    {{.Firmware.Window.Hour}}
{{- else}}
    1
{{- end}}
    {{div .Prov.ResyncSeconds 60}}
{{- /* Check-sync (spec S-5): P95030 = 0 so a plain check-sync re-provisions without a reboot (WP8x6 fw 1.0.3.20 and later) [R8x6 section 1]; P4428 = 0 authenticates the NOTIFY (ACC-16: the WP8x6 and WP856 templates say "Enable SIP NOTIFY Authentication. 0 - Yes, 1 - No" and the WP8xx one "Disable SIP NOTIFY Authentication. 0 - No, 1 - Yes"; 0 challenges in all three), which hello-sip answers from the device's HA1. */}}
    0
    0
{{- with .Book}}
    3
    {{xml .HostPath}}
    {{.RefreshMinutes}}
{{- if ne $.Phone.Family "856"}}
    1
{{- end}}
{{- end}}
    {{xml .Time.NTP}}
{{- with .Time.TZ.POSIX}}
    {{xml .}}
    {{xml .}}
{{- end}}
{{- with .Firmware}}
    {{.Via}}
    {{xml (noscheme .Dir)}}


{{- /* P238 "Firmware Upgrade and Provisioning": 0 checks at every boot, 1 only when the firmware pre/suffix changes, so with a window a reboot does not upgrade outside it. */}}
    {{if and .Window (ne $.Phone.Family "856")}}1{{else}}0{{end}}
{{- end}}
